// layout.js — guarda de sessão + menu vertical por módulo + cabeçalho (usuário e Sair).
//
// Uso nas páginas protegidas (o HTML precisa ter #loadingOverlay e um <main> dentro de #app-shell):
//   const { user, profile } = await initProtectedPage({ active: "reports", allow: can.createReport });
//
// - Sem login               -> redireciona para login.html
// - Sem perfil / inativo    -> "acesso não autorizado"
// - Perfil sem permissão    -> "acesso não autorizado"
// - Liberado                -> monta o menu, esconde o carregamento e devolve { user, profile }

import { auth, db, onAuthStateChanged, signOut, ref, get } from "./firebase-init.js";
import { h, toast } from "./utils.js";
import { ROLE, ROLE_LABEL, normalizeRole, isLegacyRole, can } from "./permissions.js";

const { ADM, DIACONO_MASTER: DM, DIACONO_CONFERENTE: DC, TESOUREIRO_MASTER: TM, TESOUREIRO_CONSULTA: TC } = ROLE;

/**
 * Itens do menu vertical. `group` agrupa por módulo; `allow(role)` decide quem vê.
 * `activeKey` permite dois itens apontarem para a mesma página.
 * Os módulos de Patrimônio, Empréstimos, Contas a pagar, Recibos e Fechamento
 * entram aqui nas próximas etapas.
 */
export const NAV = [
  { key: "home", href: "index.html", label: "Início", group: null, allow: () => true },

  { key: "generate", href: "generate.html", label: "Nova contagem", group: "Diaconia", allow: can.createReport },
  { key: "reports", href: "reports.html", label: "Histórico de Relatórios", group: "Diaconia", allow: (r) => [ADM, DM, DC].includes(r) },

  { key: "reports-t", activeKey: "reports", href: "reports.html", label: "Histórico de Relatórios", group: "Tesouraria", allow: (r) => [TM, TC].includes(r) },
  { key: "dashboard", href: "dashboard.html", label: "Dashboard", group: "Tesouraria", allow: can.viewDashboard },

  { key: "usuarios", href: "usuarios.html", label: "Usuários", group: "Administração", allow: can.manageUsers },
];

export const navFor = (role) => NAV.filter((item) => item.allow(role));

// Constante estática (sem dados do usuário), por isso pode usar innerHTML.
const LOGO_SVG = '<img src="data:image/png;base64," alt="Church Finance Logo" class="h-8 w-auto object-contain" />';
const MENU_SVG =
  '<svg viewBox="0 0 24 24" aria-hidden="true" class="h-6 w-6" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M4 6h16M4 12h16M4 18h16"/></svg>';

export async function logout() {
  try {
    await signOut(auth);
    window.location.replace("login.html");
  } catch (error) {
    console.error(error);
    toast("Não foi possível sair. Tente novamente.", "error");
  }
}

/* ------------------------------------------------------------ Estrutura */

function buildSidebar(role, active, closeDrawer) {
  const items = navFor(role);
  const groups = [...new Set(items.map((i) => i.group))];

  const link = (item) => {
    const current = (item.activeKey || item.key) === active;
    return h("a", {
      href: item.href,
      text: item.label,
      "aria-current": current ? "page" : null,
      onclick: closeDrawer,
      class: `block rounded-lg border-l-4 px-3 py-2 text-sm transition ${
        current
          ? "border-accent bg-field font-bold text-white"
          : "border-transparent font-medium text-white/80 hover:bg-field/60 hover:text-white"
      }`,
    });
  };

  const sections = groups.map((group) =>
    h(
      "div",
      { class: "mb-5" },
      group ? h("p", { class: "mb-1 px-3 text-xs font-bold uppercase tracking-wider text-muted", text: group }) : null,
      h("ul", { class: "space-y-1" }, items.filter((i) => i.group === group).map((i) => h("li", {}, link(i))))
    )
  );

  const logo = h("span", { class: "inline-flex" });
  logo.innerHTML = LOGO_SVG;

  return h(
    "aside",
    {
      id: "sidebar",
      class:
        "fixed inset-y-0 left-0 z-40 flex w-64 -translate-x-full flex-col overflow-y-auto border-r border-field bg-[#1b2917] transition-transform md:sticky md:top-0 md:h-screen md:translate-x-0 md:shrink-0",
    },
    h(
      "a",
      { href: "index.html", class: "flex items-center gap-3 border-b border-field px-4 py-4" },
      logo,
      h("span", { class: "text-lg font-bold tracking-tight", text: "Church Finance" })
    ),
    h("nav", { class: "flex-1 px-3 py-4", "aria-label": "Módulos" }, sections)
  );
}

function buildHeader(profile, toggleDrawer) {
  const menuIcon = h("span", { class: "inline-flex" });
  menuIcon.innerHTML = MENU_SVG;

  return h(
    "header",
    { class: "flex items-center justify-between gap-3 border-b border-field px-4 py-3 md:justify-end md:px-8" },
    h(
      "button",
      {
        id: "menuToggle",
        type: "button",
        "aria-label": "Abrir menu",
        "aria-controls": "sidebar",
        "aria-expanded": "false",
        class: "rounded p-1 text-white hover:bg-field md:hidden",
        onclick: toggleDrawer,
      },
      menuIcon
    ),
    h(
      "div",
      { class: "flex items-center gap-4 text-sm" },
      h("span", {
        id: "userInfo",
        class: "max-w-[14rem] truncate text-muted",
        title: `${profile.nome} · ${ROLE_LABEL[profile.role]}`,
        text: `${profile.nome} · ${ROLE_LABEL[profile.role]}`,
      }),
      h("button", {
        id: "logoutButton",
        type: "button",
        class: "rounded bg-red-600 px-3 py-1 font-medium transition hover:bg-red-700",
        text: "Sair",
        onclick: logout,
      })
    )
  );
}

function buildFooter() {
  return h("footer", {
    class: "mt-auto border-t border-field px-4 py-4 text-center text-sm",
    text: `© ${new Date().getFullYear()} Church Finance. Todos os direitos reservados.`,
  });
}

function buildShell(profile, active) {
  const shell = document.getElementById("app-shell");
  const main = shell?.querySelector("main");
  if (!shell || !main) return;

  const backdrop = h("div", { class: "fixed inset-0 z-30 hidden bg-black/60 md:hidden" });
  let sidebar;

  const setDrawer = (isOpen) => {
    sidebar.classList.toggle("-translate-x-full", !isOpen);
    backdrop.classList.toggle("hidden", !isOpen);
    document.getElementById("menuToggle")?.setAttribute("aria-expanded", String(isOpen));
  };
  const closeDrawer = () => setDrawer(false);
  const toggleDrawer = () => setDrawer(sidebar.classList.contains("-translate-x-full"));

  sidebar = buildSidebar(profile.role, active, closeDrawer);
  backdrop.addEventListener("click", closeDrawer);
  document.addEventListener("keydown", (event) => event.key === "Escape" && closeDrawer());

  shell.replaceChildren(
    h(
      "div",
      { class: "flex min-h-screen" },
      sidebar,
      backdrop,
      h("div", { class: "flex min-w-0 flex-1 flex-col" }, buildHeader(profile, toggleDrawer), main, buildFooter())
    )
  );
}

function showBlocked(overlay, message) {
  if (!overlay) return;
  overlay.classList.remove("hidden");
  overlay.replaceChildren(
    h(
      "div",
      { class: "mx-4 max-w-sm space-y-4 text-center" },
      h("h1", { class: "text-xl font-bold", text: "Acesso não autorizado" }),
      h("p", { class: "text-sm text-muted", text: message }),
      h("button", {
        type: "button",
        class: "rounded-full bg-accent px-6 py-2 text-sm font-bold text-canvas hover:brightness-95",
        text: "Sair",
        onclick: logout,
      })
    )
  );
}

/* --------------------------------------------------------------- Guarda */

export function initProtectedPage({ active, allow } = {}) {
  const overlay = document.getElementById("loadingOverlay");

  return new Promise((resolve) => {
    let released = false;

    onAuthStateChanged(auth, async (user) => {
      if (!user) {
        window.location.replace("login.html");
        return;
      }
      if (released) return;

      let raw = null;
      try {
        const snap = await get(ref(db, `users/${user.uid}`));
        raw = snap.exists() ? snap.val() : null;
      } catch (error) {
        console.error(error);
        showBlocked(overlay, "Não foi possível carregar seu perfil. Verifique a conexão e tente novamente.");
        return;
      }

      const role = normalizeRole(raw?.role);
      if (!raw || !role) {
        showBlocked(overlay, "Seu usuário ainda não tem permissão de acesso. Fale com o administrador.");
        return;
      }
      if (raw.ativo === false) {
        showBlocked(overlay, "Seu usuário está desativado. Fale com o administrador.");
        return;
      }
      if (allow && !allow(role)) {
        showBlocked(overlay, "Seu perfil não tem permissão para ver esta página.");
        return;
      }

      released = true;
      const profile = {
        nome: raw.nome || user.email || "Usuário",
        role,
        legacy: isLegacyRole(raw.role),
      };

      buildShell(profile, active);
      overlay?.classList.add("hidden");
      resolve({ user, profile });
    });
  });
}
